import React from 'react';
import './Projects.css';

const Projects = () => {
  const projects = [
    {
      id: 1,
      title: 'Adventure Quest RPG',
      description: 'An open-world RPG featuring dynamic combat systems, quest management, and stunning environments built with Unreal Engine 5.',
      image: null,
      tags: ['Unreal Engine', 'C++', 'Blueprints', 'Open World'],
      category: 'RPG'
    },
    {
      id: 2,
      title: 'Space Defender',
      description: 'A fast-paced arcade shooter with procedurally generated levels, power-up systems, and leaderboard integration.',
      image: null,
      tags: ['Unity', 'C#', 'Mobile', 'Arcade'],
      category: 'Shooter'
    },
    {
      id: 3,
      title: 'Puzzle Kingdom',
      description: 'A brain-teasing puzzle game with 100+ levels, beautiful art style, and satisfying mechanics.',
      image: null,
      tags: ['Unity', 'C#', 'Puzzle', 'Casual'],
      category: 'Puzzle'
    },
    {
      id: 4,
      title: 'VR Racing Experience',
      description: 'An immersive VR racing game with realistic physics, multiple tracks, and multiplayer support.',
      image: null,
      tags: ['Unreal Engine', 'VR', 'Multiplayer', 'Racing'],
      category: 'Racing'
    },
    {
      id: 5,
      title: 'Survival Island',
      description: 'A survival game featuring crafting systems, day-night cycles, and dynamic weather.',
      image: null,
      tags: ['Unity', 'C#', 'Survival', 'Crafting'],
      category: 'Survival'
    },
    {
      id: 6,
      title: 'Tower Defense Pro',
      description: 'A strategic tower defense game with unique tower abilities, boss battles, and endless mode.',
      image: null,
      tags: ['Unity', 'C#', 'Strategy', 'Mobile'],
      category: 'Strategy'
    }
  ];

  return (
    <section id="projects" className="projects">
      <div className="container">
        <h2 className="section-title">Featured Projects</h2>
        
        <div className="projects-grid">
          {projects.map((project) => (
            <div className="project-card" key={project.id}>
              <div className="project-image">
                <div className="project-placeholder">
                  <span className="project-category">{project.category}</span>
                </div>
                <div className="project-overlay">
                  <button className="project-btn">View Details</button>
                </div>
              </div>
              <div className="project-info">
                <h3>{project.title}</h3>
                <p>{project.description}</p>
                <div className="project-tags">
                  {project.tags.map((tag, index) => (
                    <span className="tag" key={index}>{tag}</span>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Projects;
